{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table snitch_db.maplemonk.planned_inwarded_data as WITH base AS ( SELECT UPPER(TRIM(cleaned_sku)) AS sku_group, TRY_TO_NUMBER( REPLACE(TRIM(qty), \',\', \'\') ) AS planned_qty, CASE WHEN remarks_final ILIKE \'JAN%\' THEN 1 WHEN remarks_final ILIKE \'FEB%\' THEN 2 WHEN remarks_final ILIKE \'MAR%\' THEN 3 WHEN remarks_final ILIKE \'APR%\' THEN 4 WHEN remarks_final ILIKE \'MAY%\' THEN 5 WHEN remarks_final ILIKE \'JUN%\' THEN 6 WHEN remarks_final ILIKE \'JUL%\' THEN 7 WHEN remarks_final ILIKE \'AUG%\' THEN 8 WHEN remarks_final ILIKE \'SEP%\' THEN 9 WHEN remarks_final ILIKE \'OCT%\' THEN 10 WHEN remarks_final ILIKE \'NOV%\' THEN 11 WHEN remarks_final ILIKE \'DEC%\' THEN 12 ELSE NULL END AS planned_month FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks ), base_unique AS ( SELECT sku_group, planned_month, planned_qty FROM base WHERE planned_month BETWEEN 4 AND 9 QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group, planned_month ORDER BY sku_group ) = 1 ), category AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, l1_category, category, meta1, meta2, meta3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(sku_group)) ORDER BY sku_group ) = 1 ), base_with_category AS ( SELECT b.sku_group, b.planned_month, b.planned_qty, c.l1_category, c.category, c.meta1, c.meta2, c.meta3 FROM base_unique b LEFT JOIN category c ON b.sku_group = c.sku_group ), planned_summary AS ( SELECT planned_month, l1_category, category, meta1, meta2, meta3, SUM(planned_qty) AS planned_qty FROM base_with_category GROUP BY planned_month, l1_category, category, meta1, meta2, meta3 ), base_ranked AS ( SELECT sku_group, planned_month, planned_qty, l1_category, category, meta1, meta2, meta3, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY planned_month ASC ) AS rn FROM base_with_category ), inward AS ( SELECT UPPER( TRIM( REGEXP_REPLACE( \"Item Type skuCode\", \'-[0-9A-Za-z]{1,5}$\', \'\' ) ) ) AS sku_group, MONTH(putaway_completed_date) AS inward_month, SUM( putaway_completed_quantity ) AS inwarded_qty FROM snitch_db.maplemonk.putaway_tracking WHERE final_type ILIKE \'New inward\' AND \"Putaway Item Status Code\" ILIKE \'complete\' AND is_trading ILIKE \'True\' GROUP BY 1, 2 HAVING SUM(putaway_completed_quantity) > 100 AND MONTH(putaway_completed_date) BETWEEN 4 AND 9 ), inward_ranked AS ( SELECT sku_group, inward_month, inwarded_qty, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY inward_month ASC ) AS rn FROM inward ), matched AS ( SELECT b.sku_group, b.planned_month, b.planned_qty, b.l1_category, b.category, b.meta1, b.meta2, b.meta3, CASE WHEN i.inward_month >= b.planned_month - 2 THEN i.inward_month ELSE NULL END AS inward_month, CASE WHEN i.inward_month >= b.planned_month - 2 THEN i.inwarded_qty ELSE NULL END AS inwarded_qty FROM base_ranked b LEFT JOIN inward_ranked i ON b.sku_group = i.sku_group AND b.rn = i.rn ), journey AS ( SELECT planned_month, l1_category, category, meta1, meta2, meta3, SUM( CASE WHEN inward_month = 4 THEN COALESCE(inwarded_qty, 0) ELSE 0 END ) AS apr_inward, SUM( CASE WHEN inward_month = 5 THEN COALESCE(inwarded_qty, 0) ELSE 0 END ) AS may_inward, SUM( CASE WHEN inward_month = 6 THEN COALESCE(inwarded_qty, 0) ELSE 0 END ) AS june_inward, SUM( CASE WHEN inward_month = 7 THEN COALESCE(inwarded_qty, 0) ELSE 0 END ) AS july_inward, SUM( CASE WHEN inward_month = 8 THEN COALESCE(inwarded_qty, 0) ELSE 0 END ) AS august_inward, SUM( CASE WHEN inward_month = 9 THEN COALESCE(inwarded_qty, 0) ELSE 0 END ) AS sept_inward FROM matched GROUP BY planned_month, l1_category, category, meta1, meta2, meta3 ) SELECT CASE WHEN p.planned_month = 4 THEN \'April\' WHEN p.planned_month = 5 THEN \'May\' WHEN p.planned_month = 6 THEN \'June\' WHEN p.planned_month = 7 THEN \'July\' WHEN p.planned_month = 8 THEN \'August\' WHEN p.planned_month = 9 THEN \'September\' END AS month, p.l1_category, p.category, p.meta1, p.meta2, p.meta3, p.planned_qty, COALESCE(j.apr_inward, 0) AS apr_inward, COALESCE(j.may_inward, 0) AS may_inward, COALESCE(j.june_inward, 0) AS june_inward, COALESCE(j.july_inward, 0) AS july_inward, COALESCE(j.august_inward, 0) AS august_inward, COALESCE(j.sept_inward, 0) AS sept_inward, ROUND( 100.0 * ( COALESCE(j.apr_inward, 0) + COALESCE(j.may_inward, 0) + COALESCE(j.june_inward, 0) + COALESCE(j.july_inward, 0) + COALESCE(j.august_inward, 0) + COALESCE(j.sept_inward, 0) ) / NULLIF(p.planned_qty, 0), 2 ) AS inwarded_pct FROM planned_summary p LEFT JOIN journey j ON p.planned_month = j.planned_month AND COALESCE(p.l1_category, \'\') = COALESCE(j.l1_category, \'\') AND COALESCE(p.category, \'\') = COALESCE(j.category, \'\') AND COALESCE(p.meta1, \'\') = COALESCE(j.meta1, \'\') AND COALESCE(p.meta2, \'\') = COALESCE(j.meta2, \'\') AND COALESCE(p.meta3, \'\') = COALESCE(j.meta3, \'\') ORDER BY p.planned_month, p.l1_category, p.category, p.meta1, p.meta2, p.meta3;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            